SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷98·安重荣传·宗城之战", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/jiuwudaishi-098-zongcheng/source.txt", "note": "《旧五代史》卷98·安重荣传·宗城之战，段落 jiu-wudaishi-205deb4a7860-p002394；已核上下文及传主，纸本及异文待核。", "id": "77f1f691-8569-5ce3-b70b-59af25e7625c"}, {"title": "资治通鉴·卷282·天福六年十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/tongjian-282-941-year-end/source.txt", "note": "《资治通鉴》卷282·天福六年十二月，段落 zizhi-tongjian-a63549944a71-p003359；已核上下文及传主，纸本及异文待核。", "id": "b7766ba2-e02b-5360-98d4-3800e412d4b6"}, {"title": "资治通鉴·卷282·四部丛刊本第163页·安重荣南行", "source_type": "primary", "author": "司马光等", "edition": "维基文库四部丛刊本第163页固定修订1471339；逐字Wikitext保留，影印字形及纸本待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/tongjian-282-941-year-end-collation/source.txt", "note": "《资治通鉴》四部丛刊本卷282，第163页转录，固定修订1471339；同书电子版本校读，影印字形及纸本待核。", "id": "e03d6f3c-47c0-5598-94c8-e691718ff49b"}, {"title": "新五代史·卷51·安重荣传·宗城之战", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/xinwudaishi-051-zongcheng/source.txt", "note": "《新五代史》卷51·安重荣传·宗城之战，段落 xin-wudaishi-b08f244b9241-p002004；已核上下文及传主，纸本及异文待核。", "id": "db0641bc-c32f-5077-a5c2-ef76385d9e13"}, {"title": "新五代史·卷65·南汉世家·刘龑改名", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/058e3fb21c9297c339adaaf269129242f63ad9e2/content/books/zizhi-tongjian/vol-282/year-0941/part-06/sources/library/xinwudaishi-065-liu-yan-rename/source.txt", "note": "《新五代史》卷65·南汉世家·刘龑改名，段落 xin-wudaishi-b08f244b9241-p003270；已核上下文及传主，纸本及异文待核。", "id": "7365cbed-e41d-5021-92b9-0a21102a515b"}, {"title": "资治通鉴·卷282·天福六年九月至十二月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/tongjian-282-941-autumn-winter/source.txt", "note": "《资治通鉴》卷282·天福六年九月至十二月，段落 zizhi-tongjian-a63549944a71-p003358；已核上下文及传主，纸本及异文待核。", "id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"title": "旧五代史·卷80·晋高祖纪·天福六年十二月奏十一月战事", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/179342146c1d78cfe3d5641c28e7db199f4e8b59/content/books/zizhi-tongjian/vol-282/year-0941/part-05/sources/library/jiuwudaishi-080-an-congjin-battle/source.txt", "note": "《旧五代史》卷80·晋高祖纪·天福六年十二月奏十一月战事，段落 jiu-wudaishi-205deb4a7860-p001965；已核上下文及传主，纸本及异文待核。", "id": "730c5b92-8047-5888-94e1-7917e27fa2d8"}, {"title": "新五代史·卷69·南平世家·安从进求援", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6a1f52aa71e10dbcefa59b542374cb6f53ccd662/content/books/zizhi-tongjian/vol-282/year-0941/part-02/sources/library/xinwudaishi-069-an-congjin-aid/source.txt", "note": "《新五代史》卷69·南平世家·安从进求援，段落 xin-wudaishi-b08f244b9241-p003430；已核上下文及传主，纸本及异文待核。", "id": "7a698ee2-b948-5537-89a1-b08419e3b21f"}]'::jsonb)
