INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "王绍颜", "aliases": ["王紹顏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐内侍。941年向李昪上书，指出春季以来许多群臣获罪，朝廷内外疑惧。李昪亲笔解释缘由，命王绍颜告知内外。生卒年未载。", "biography": null, "status": "draft", "id": "7b5d4362-d9f5-5b07-897d-a785905d4914"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "李德珫", "aliases": ["李德充"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋建雄节度使。940年三月调任北都留守。《旧五代史》同次从晋州到北京的调任写作李德充，按任职与行动对应识别为同一人，保留原文字形说明。生卒年未载。", "biography": null, "status": "draft", "id": "0263c149-1d66-5360-8ad2-9b565aa3d34e"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "高从诲", "aliases": ["高從誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光三年条所见人物：高从诲。", "biography": null, "status": "draft", "id": "361de308-8df0-56e4-ac98-81f6b9297e26"}, {"name": "李端", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荆南都指挥使。941年十二月受高从诲派遣，率数千水军到南津，协助高行周讨安从进，并运粮供应。生卒年未载。", "biography": null, "status": "draft", "id": "ce359100-a42e-5823-92eb-c22e62390d91"}, {"name": "马希范", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平三年条所见人物：马希范。", "biography": null, "status": "draft", "id": "6c13c07c-57cf-596e-9247-ba0556ac4737"}, {"name": "张少敌", "aliases": ["張少敵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国天策都军使，张佶之子。941年十二月受马希范派遣，率一百五十艘战舰进入汉江，协助高行周讨安从进，并运粮供应。生卒年未载。", "biography": null, "status": "draft", "id": "e3c9c29f-0e6a-5dc5-a207-36eae30e98bb"}, {"name": "张佶", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张佶。", "biography": null, "status": "draft", "id": "3e2c7882-9436-5f5d-8d37-e452a1db7890"}, {"name": "安重荣", "aliases": ["安重榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安重荣，转投者。", "biography": null, "status": "draft", "id": "7309cd08-206a-5781-8eaa-527f54f64299"}, {"name": "赵彦之", "aliases": ["趙彥之"], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "深州人，早年与安重荣同为散指挥使，相互交好。安重荣镇成德后，赵彦之从关西归来，受命募众；安重荣后来只任他排陈使，赵彦之怨恨。941年十二月宗城战中卷旗来降后晋，被官军杀死并分取银饰装备。出生年未载。", "biography": null, "status": "draft", "id": "ae669257-a502-5396-8aea-9aa3c0221d1b"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "王周", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262天复元年条所见人物：王周。", "biography": null, "status": "draft", "id": "dcf3a493-1cbc-5185-9787-8041333d1d90"}, {"name": "安从进", "aliases": ["安從進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安从进，受询的侍卫都指挥使。", "biography": null, "status": "draft", "id": "3b1f48e5-6ce0-58cd-add7-1bdf9f0d4812"}, {"name": "安从贵", "aliases": ["安從貴"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安从进的弟弟。941年奉兄长派遣，率兵迎击均州刺史蔡行遇，被焦继勋截击击败，被俘并遭断足后送回。出生年及死亡年未载。", "biography": null, "status": "draft", "id": "72a84a89-ecbd-5f27-bf84-9e6dd9fa8837"}, {"name": "蔡行遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋均州刺史。941年安从进派其弟安从贵率兵迎击蔡行遇，焦继勋截击安从贵并取胜。生卒年未载。", "biography": null, "status": "draft", "id": "c657ba32-a6f0-5c36-b7f0-d962ecf51cc4"}, {"name": "焦继勋", "aliases": ["焦繼勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋武德使。941年十一月受石重贵派遣，与张从恩、郭金海、陈思让领大梁兵讨伐安从进；旧史奏报中也列其参与唐州以南战役。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a397d94d-0b6a-5593-9f5e-c39132813767"}, {"name": "王重胤", "aliases": ["王重𦙍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋指挥使，宛丘人。941年十二月戊戌宗城战中，劝杜重威不要退军，建议分兵攻击镇州军两翼，自己直冲中军。杜重威接受建议。生卒年未载。", "biography": null, "status": "draft", "id": "63920eda-9027-5fb4-b138-0f4d9dbd2bcf"}, {"name": "杨彦询", "aliases": ["楊彥詢"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨彦询，获任副留守者。", "biography": null, "status": "draft", "id": "d829ba3f-56da-5e63-8216-680ff37456ce"}, {"name": "张建武", "aliases": ["張建武"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋冀州刺史。941年十二月庚子与其他将领攻取赵州。生卒年未载。", "biography": null, "status": "draft", "id": "7765b3b9-ef54-547e-88e3-6127aca4d1db"}, {"name": "刘岩", "aliases": ["刘龑", "劉巖", "劉龑", "劉岩", "刘巖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平四年条所见人物：刘岩。", "biography": null, "status": "draft", "id": "3b676280-64ca-5ba9-b78d-c6c5f257a018"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

