SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "李昪：史书记其生活节俭，勤于政务。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：唐主性节俭，常蹑蒲屦，盥颒用铁盎，暑则寝于青葛帷，左右使令惟老丑宫人，服饰粗略。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "981b47a6-cc5a-5828-aae1-1de574e7ea30", "subject_id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person", "field_path": "biography", "claim_text": "《资治通鉴》记李昪生活节俭，常穿蒲草鞋，用铁盆洗脸，夏天睡在葛布帷帐内，衣饰简朴。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：唐主性节俭，常蹑蒲屦，盥颒用铁盎，暑则寝于青葛帷，左右使令惟老丑宫人，服饰粗略。；核对说明：这些是长期生活习惯的概述，不造一场941年单日节俭事件；宫人相貌的贬称保留在原文，不扩为网站人物评价。", "status": "draft", "id": "2ea83fb9-6b1d-5bbe-a357-6bdbe0a82c23", "subject_id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "description", "claim_text": "李昪规定为国事而死者，即使是普通士卒，也给禄三年。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：死国事者虽士卒皆给禄三年。；核对说明：三年为给禄期限，不补每人钱额或假定每份给付已完成。", "status": "draft", "id": "93a0b02d-0be9-56eb-abe3-9d84f92c9b52", "subject_id": "f62539dd-82dd-5099-bad5-fdfd89416f49", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "李昪在位期间，具体年月未载", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：死国事者虽士卒皆给禄三年。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "06caa791-dcad-57da-9b27-e7738c0efbb5", "subject_id": "f62539dd-82dd-5099-bad5-fdfd89416f49", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李昪：规定对为国事而死者给禄三年。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：死国事者虽士卒皆给禄三年。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c20c1002-5c17-538b-aa61-a41defe759d3", "subject_id": "fc060a7a-ce26-5b9e-8c10-36967cf5d853", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "description", "claim_text": "李昪派使者察看民田，按土地肥瘠确定税额。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：分遣使者按行民田，以肥瘠定其税，；核对说明：使者未具名，税率及具体田块未载。", "status": "draft", "id": "8a5ed219-36c9-5020-b042-bd7848b7e7c1", "subject_id": "30587280-92ac-5675-9351-72d910f5bbfb", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "李昪在位期间，具体年月未载", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：分遣使者按行民田，以肥瘠定其税，；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "f0d256be-2f10-5e0b-8fef-4d2a1a92626c", "subject_id": "30587280-92ac-5675-9351-72d910f5bbfb", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李昪：派使者查田并按肥瘠确定税额。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：分遣使者按行民田，以肥瘠定其税，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b10e208f-d365-567a-aa4a-1ac5248957ef", "subject_id": "7bed661f-5577-530f-baa5-15d9e350ec25", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》记百姓认为这种田税安排较为公平，此后江淮调兵、征役和其他赋敛都以税钱为基准。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：民间称其平允。自是江、淮调兵兴役及它赋敛，皆以税钱为率，至今用之。；核对说明：民间称为史书记述的反应，至今用之为作者回顾，不确定其最后适用日期。", "status": "draft", "id": "2aa7214c-91c2-5398-b804-cc1df98a3223", "subject_id": "30587280-92ac-5675-9351-72d910f5bbfb", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person", "field_path": "biography", "claim_text": "《资治通鉴》记李昪日夜处理政务，从江都返回后不再宴乐，但也批评他过于急躁。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：唐主勤于听政，以夜继昼，还自江都，不复宴乐；颇伤躁急，；核对说明：评价与在位期间行为概述保留，不重复造一场941年返回江都的新行程。", "status": "draft", "id": "5c768a3a-459e-53f2-ba79-9c7d55fdd58a", "subject_id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "description", "claim_text": "内侍王绍颜向李昪上书，说从当年春天以来，许多群臣获罪，朝廷内外疑虑恐惧。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：内侍王绍颜上书，以为“今春以来，群臣获罪者众，中外疑惧。”；核对说明：疑惧程度为王绍颜的报告，不补受罚名单或人数。", "status": "draft", "id": "248c3bc0-8b75-5591-aaf4-df84dddded39", "subject_id": "712ff4cf-b6f7-5bc5-83c3-5bb7a4281ed2", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "941年年末条下，具体日期未载", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：内侍王绍颜上书，以为“今春以来，群臣获罪者众，中外疑惧。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "79961244-d2d0-543c-ba5a-d09d66777ccf", "subject_id": "712ff4cf-b6f7-5bc5-83c3-5bb7a4281ed2", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person", "field_path": "description", "claim_text": "王绍颜：向李昪上书反映内外疑惧。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：内侍王绍颜上书，以为“今春以来，群臣获罪者众，中外疑惧。”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "882e8995-7957-54a8-8748-7d0cc583bce5", "subject_id": "7b5d4362-d9f5-5b07-897d-a785905d4914", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1eb304"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王绍颜：向李昪上书反映内外疑惧。", "citation": "卷282·后晋天福六年（941；年末条下及相关追述）·zztj-v282-y0941-p030·原文件第115行", "note": "原文：内侍王绍颜上书，以为“今春以来，群臣获罪者众，中外疑惧。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "38446822-0e73-5102-a610-b49a240b7a3b", "subject_id": "f63d074b-7855-57b5-91c7-802976774655", "source_id": "a0bfbd8b-2660-5734-857f-5b507a1e